Here is the commit message:
async_pq_val: fix DMA memory leak

Add missing dmaengine_unmap_put(), so we don't OOM during RAID6 sync.

Fixes: 1786b943dad0 ("async_pq_val: convert to dmaengine_unmap_data")
Signed-off-by: Justin Maggard <jmaggard@netgear.com>
Reviewed-by: Dan Williams <dan.j.williams@intel.com>
Cc: <stable@vger.kernel.org>
Signed-off-by: Vinod Koul <vinod.koul@intel.com>

Here is the root cause:
The bug was caused by a missing call to `dmaengine_unmap_put()`, which is responsible for releasing DMA resources after they are no longer needed. This omission led to a memory leak, resulting in out-of-memory (OOM) conditions during RAID6 synchronization operations.

Here is the patch:
  */
 struct dma_async_tx_descriptor *
 async_syndrome_val(struct page **blocks, unsigned int offset, int disks,
 		   size_t len, enum sum_check_flags *pqres, struct page *spare,
 		   struct async_submit_ctl *submit)
 {
 	struct dma_chan *chan = pq_val_chan(submit, blocks, disks, len);
 	struct dma_device *device = chan ? chan->device : NULL;
 	struct dma_async_tx_descriptor *tx;
 	unsigned char coefs[disks-2];
 	enum dma_ctrl_flags dma_flags = submit->cb_fn ? DMA_PREP_INTERRUPT : 0;
 	struct dmaengine_unmap_data *unmap = NULL;

 	BUG_ON(disks < 4);

 	if (device)
 		unmap = dmaengine_get_unmap_data(device->dev, disks, GFP_NOWAIT);

 	if (unmap && disks <= dma_maxpq(device, 0) &&
 	    is_dma_pq_aligned(device, offset, 0, len)) {
 		struct device *dev = device->dev;
 		dma_addr_t pq[2];
 		int i, j = 0, src_cnt = 0;

 		pr_debug("%s: (async) disks: %d len: %zu\n",
 			 __func__, disks, len);

 		unmap->len = len;
 		for (i = 0; i < disks-2; i++)
 			if (likely(blocks[i])) {
 				unmap->addr[j] = dma_map_page(dev, blocks[i],
 							      offset, len,
 							      DMA_TO_DEVICE);
 				coefs[j] = raid6_gfexp[i];
 				unmap->to_cnt++;
 				src_cnt++;
 				j++;
 			}

 		if (!P(blocks, disks)) {
 			pq[0] = 0;
 			dma_flags |= DMA_PREP_PQ_DISABLE_P;
 		} else {
 			pq[0] = dma_map_page(dev, P(blocks, disks),
 					     offset, len,
 					     DMA_TO_DEVICE);
 			unmap->addr[j++] = pq[0];
 			unmap->to_cnt++;
 		}
 		if (!Q(blocks, disks)) {
 			pq[1] = 0;
 			dma_flags |= DMA_PREP_PQ_DISABLE_Q;
 		} else {
 			pq[1] = dma_map_page(dev, Q(blocks, disks),
 					     offset, len,
 					     DMA_TO_DEVICE);
 			unmap->addr[j++] = pq[1];
 			unmap->to_cnt++;
 		}

 		if (submit->flags & ASYNC_TX_FENCE)
 			dma_flags |= DMA_PREP_FENCE;
 		for (;;) {
 			tx = device->device_prep_dma_pq_val(chan, pq,
 							    unmap->addr,
 							    src_cnt,
 							    coefs,
 							    len, pqres,
 							    dma_flags);
 			if (likely(tx))
 				break;
 			async_tx_quiesce(&submit->depend_tx);
 			dma_async_issue_pending(chan);
 		}

 		dma_set_unmap(tx, unmap);
 		async_tx_submit(chan, tx, submit);
-
-		return tx;
 	} else {
 		struct page *p_src = P(blocks, disks);
 		struct page *q_src = Q(blocks, disks);
 		enum async_tx_flags flags_orig = submit->flags;
 		dma_async_tx_callback cb_fn_orig = submit->cb_fn;
 		void *scribble = submit->scribble;
 		void *cb_param_orig = submit->cb_param;
 		void *p, *q, *s;

 		pr_debug("%s: (sync) disks: %d len: %zu\n",
 			 __func__, disks, len);

 		/* caller must provide a temporary result buffer and
 		 * allow the input parameters to be preserved
 		 */
 		BUG_ON(!spare || !scribble);

 		/* wait for any prerequisite operations */
 		async_tx_quiesce(&submit->depend_tx);

 		/* recompute p and/or q into the temporary buffer and then
 		 * check to see the result matches the current value
 		 */
 		tx = NULL;
 		*pqres = 0;
 		if (p_src) {
 			init_async_submit(submit, ASYNC_TX_XOR_ZERO_DST, NULL,
 					  NULL, NULL, scribble);
 			tx = async_xor(spare, blocks, offset, disks-2, len, submit);
 			async_tx_quiesce(&tx);
 			p = page_address(p_src) + offset;
 			s = page_address(spare) + offset;
 			*pqres |= !!memcmp(p, s, len) << SUM_CHECK_P;
 		}

 		if (q_src) {
 			P(blocks, disks) = NULL;
 			Q(blocks, disks) = spare;
 			init_async_submit(submit, 0, NULL, NULL, NULL, scribble);
 			tx = async_gen_syndrome(blocks, offset, disks, len, submit);
 			async_tx_quiesce(&tx);
 			q = page_address(q_src) + offset;
 			s = page_address(spare) + offset;
 			*pqres |= !!memcmp(q, s, len) << SUM_CHECK_Q;
 		}

 		/* restore P, Q and submit */
 		P(blocks, disks) = p_src;
 		Q(blocks, disks) = q_src;

 		submit->cb_fn = cb_fn_orig;
 		submit->cb_param = cb_param_orig;
 		submit->flags = flags_orig;
 		async_tx_sync_epilog(submit);
-
-		return NULL;
+		tx = NULL;
 	}
+	dmaengine_unmap_put(unmap);
+
+	return tx;
 }
 EXPORT_SYMBOL_GPL(async_syndrome_val);


